import{_ as s,o as i,c as a,X as t}from"./chunks/framework.CNGPadWr.js";const k=JSON.parse('{"title":"API example service","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/docs/example-service.md","filePath":"playground/README.md"}'),n={name:"rust/docs/example-service.md"};function r(p,e,l,o,d,h){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="api-example-service" tabindex="-1">API example service <a class="header-anchor" href="#api-example-service" aria-label="Permalink to &quot;API example service&quot;">​</a></h1><p>The static API reference includes highlighted, read-only examples. A separate service runs fixed, prebuilt programs and provides read-only rust-analyzer hover information. Visitors cannot submit code, change a document, add arguments, or navigate definitions outside the selected file.</p><h2 id="prepare-on-a-build-worker" tabindex="-1">Prepare on a build worker <a class="header-anchor" href="#prepare-on-a-build-worker" aria-label="Permalink to &quot;Prepare on a build worker&quot;">​</a></h2><p>Use an authorized Linux worker with Rust 1.96.0 and its <code>rust-src</code> component, rust-analyzer, GCC, bubblewrap with <code>--size</code> support, and <code>prlimit</code>. Follow your environment&#39;s compute and network rules.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack/playground/prepare.py</span></span></code></pre></div><p>Preparation uses the Cargo cache offline, vendors the locked dependencies, and builds the three approved example binaries. It snapshots their source and fixture. Re-run preparation after changing the library or examples. Stop the service before replacing prepared inputs and deploy the matching website and prepared service together. <code>CELLPACK_BWRAP</code> can select a bubblewrap executable outside <code>PATH</code>.</p><h2 id="start-and-connect" tabindex="-1">Start and connect <a class="header-anchor" href="#start-and-connect" aria-label="Permalink to &quot;Start and connect&quot;">​</a></h2><p>To serve the built website and fixed examples together on one origin:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack/playground/server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack/_build/html</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000</span></span></code></pre></div><p>Use <code>--base /en/latest/</code> when the website was built with that prefix. This combined server handles the example endpoints itself; a plain static file server cannot handle <strong>Run example</strong> or LSP requests.</p><p>To keep an existing web server and reverse proxy the example service separately:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack/playground/server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://docs.example.org</span></span></code></pre></div><p>The service listens on <code>127.0.0.1:8091</code>. Reverse proxy the website&#39;s <code>/playground/</code> prefix to it, removing that prefix and enabling WebSocket upgrades. With a site base such as <code>/en/latest/</code>, proxy <code>/en/latest/playground/</code> instead. The frontend defaults to this same-origin path. <code>CELLPACK_PLAYGROUND_URL</code> can select a different endpoint at website build time. Supply <code>--origin</code> once per allowed browser origin, including scheme and port.</p><p>For worker-local development:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CELLPACK_PLAYGROUND_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://127.0.0.1:8091</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5191</span></span></code></pre></div><p>Use <code>--origin http://127.0.0.1:5191</code> on the service for this preview. Production hosting needs its own reverse proxy; static VitePress output does not start the Python service.</p><h2 id="request-contract" tabindex="-1">Request contract <a class="header-anchor" href="#request-contract" aria-label="Permalink to &quot;Request contract&quot;">​</a></h2><p><code>POST /run</code> accepts exactly one field:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;example&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Allowed IDs are <code>write</code>, <code>selection</code>, and <code>loading</code>. Additional fields, source code, paths, arguments, and unknown IDs are rejected. The request runs an approved binary built during preparation; it never compiles submitted source.</p><p><code>GET /lsp?example=write&amp;file=main.rs</code> opens read-only analysis of a fixed example. Only <code>main.rs</code> and <code>common.rs</code> are accepted. The server supplies the approved source regardless of text sent by the client. Document changes and arbitrary file reads are rejected. Definition results outside the selected file are filtered out on the server, and the browser applies the same restriction. Hover text never opens external links. Switching file tabs closes the previous analysis session.</p><p><code>GET /health</code> reports readiness, the prepared library build ID, and toolchain. The server probes isolated compiler/analyzer startup before accepting requests.</p><h2 id="resource-boundary" tabindex="-1">Resource boundary <a class="header-anchor" href="#resource-boundary" aria-label="Permalink to &quot;Resource boundary&quot;">​</a></h2><p>The example programs and analyzer run in bubblewrap with separate user, PID, and network namespaces. The host home, datasets, and credentials are not mounted. The sandbox sees the toolchain, system libraries, prepared binaries, public crate sources, vendored dependencies, and fixed example files. Inputs are read-only. Temporary storage uses bounded tmpfs: 128 MiB at <code>/tmp</code>, 512 MiB at <code>/work</code>. <code>prlimit</code> bounds address space, CPU time, process count, file size, and descriptors. There is no host execution fallback.</p><p>There are two run slots and two analysis slots. Runs have a 50-second wall limit and a 64 KiB limit per output stream. Analysis expires after five minutes or two idle minutes. Client disconnects cancel active runs and close analyzers. Use a dedicated unprivileged service account and service-level cgroup limits, plus rate limiting at the public reverse proxy.</p><h2 id="maintain-and-validate" tabindex="-1">Maintain and validate <a class="header-anchor" href="#maintain-and-validate" aria-label="Permalink to &quot;Maintain and validate&quot;">​</a></h2><p><code>api_content.py</code> contains explanations and expected outputs. <code>api-examples/*.rs</code> contains the fixed programs; <code>examples/common.rs</code> contains the shared fixture. <code>reference.py</code> generates declarations, type links, source excerpts, and the example catalog. Shiki highlights the examples at build time, including without JavaScript. CodeMirror supplies the optional read-only LSP viewer.</p><p>On the authorized worker, after preparation:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack/playground/test_server.py</span></span></code></pre></div><p><code>test_browser.py</code> exercises the browser with <code>CELLPACK_REVIEW_URL</code> pointing to a preview and <code>CELLPACK_CHROMIUM</code> optionally selecting its Chromium executable.</p>`,30)])])}const u=s(n,[["render",r]]);export{k as __pageData,u as default};
